/* Supabase-backed accounts, authenticated avatars, accepted text conversations and cooperative missions. */
(() => {
  'use strict';
  const $=id=>document.getElementById(id),game=window.gameOnline;
  if(!game)return;
  let client=null,user=null,profile=null,signup=false,recovering=false,generation=0,connecting=false;
  let group=null,groupVersion=-1,groupChannel=null,selfChannel=null,selfReady=false,accountChannel=null,chatChannel=null,activeChat=null;
  let roster=new Map(),peerChannels=new Map(),profiles=new Map(),blocked=new Set(),conversations=[],invitations=[],members=[];
  let lastPose=0,lastPoseText='',lastHeartbeat=0,lastRefresh=0,refreshing=false,busyAction=false,pendingInvite=null;
  let pendingSave=null,saveTimer=null,saving=null,seenInvites=new Set(),realtimeTimer=null;
  const uuid=()=>crypto.randomUUID(),status=text=>{$('online-status').textContent=text;},notice=text=>{status(text);game.toast(text);};
  const el=(tag,text,className)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;if(className)e.className=className;return e;};
  const button=(text,fn,cls='online-small')=>{const b=el('button',text,cls);b.type='button';b.onclick=()=>run(fn,b);return b;};
  function errorText(error){const m=String(error?.message||error||'');if(/Invalid login credentials/i.test(m))return 'Confira o e-mail e a senha.';if(/Email not confirmed/i.test(m))return 'Confirme seu e-mail antes de entrar.';if(/rate limit/i.test(m))return 'Muitas tentativas. Aguarde um pouco e tente novamente.';if(/fetch|network|timeout/i.test(m))return 'Conexão interrompida. Confira sua internet e tente novamente.';if(/password/i.test(m))return 'Use uma senha com pelo menos 10 caracteres.';return m.slice(0,190)||'Não foi possível concluir. Tente novamente.';}
  async function run(fn,b){if(b)b.disabled=true;try{return await fn();}catch(e){notice(errorText(e));}finally{if(b)b.disabled=false;}}
  async function rpc(name,args){const {data,error}=await client.rpc(name,args);if(error)throw error;return data;}
  function openPanel(tab='players'){game.clearInput();if($('welcome').open)$('welcome').close();if(!$('online-dialog').open)$('online-dialog').showModal();selectTab(tab);if(user)run(refresh);}
  function closePanel(){$('online-dialog').close();if(!game.started())$('welcome').showModal();}
  function selectTab(tab){for(const n of ['players','chat','group','account'])$('online-panel-'+n).hidden=n!==tab;document.querySelectorAll('[data-online-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.onlineTab===tab)));}
  function updateBadge(){const count=roster.size;$('online-launcher').classList.toggle('connected',!!user&&selfReady);$('online-badge').textContent=user?(selfReady?(count?count+' outro'+(count>1?'s jogadores':' jogador')+' online':'Você está online'):'Reconectando…'):'Conta, avatar e conversas';}
  async function loadProfile(id){if(profiles.has(id))return profiles.get(id);const {data,error}=await client.from('player_profiles').select('id,display_name,color,skin,hair').eq('id',id).single();if(error)throw error;profiles.set(id,data);return data;}
  function avatarPreview(){const p=$('online-avatar-preview');p.style.setProperty('--shirt',$('online-color').value);p.style.setProperty('--skin',$('online-skin').value);p.style.setProperty('--hair',$('online-hair').value);}
  function fillProfile(){if(!profile)return;$('online-display-name').value=profile.display_name;$('online-color').value=profile.color;$('online-skin').value=profile.skin;$('online-hair').value=profile.hair;avatarPreview();}
  async function teardown(){generation++;clearTimeout(saveTimer);clearTimeout(realtimeTimer);pendingSave=null;activeChat=null;selfReady=false;const old=client;const channels=[accountChannel,selfChannel,chatChannel,groupChannel,...peerChannels.values()];accountChannel=selfChannel=chatChannel=groupChannel=null;peerChannels.clear();for(const id of roster.keys())game.removePeer(id);roster.clear();profiles.clear();blocked.clear();conversations=[];invitations=[];members=[];group=null;groupVersion=-1;game.leaveGroup();if(old)await Promise.allSettled(channels.filter(Boolean).map(ch=>old.removeChannel(ch)));}
  async function connect(session){
    if(!session?.user){if(user){await teardown();user=profile=null;game.guest();}$('online-connected').hidden=true;$('online-login').hidden=false;updateBadge();return;}
    if(user?.id===session.user.id||connecting)return;
    connecting=true;try{
      await teardown();const current=++generation;const nextUser=session.user;
      const {data:existing,error:profileError}=await client.from('player_profiles').select('id,display_name,color,skin,hair').eq('id',nextUser.id).maybeSingle();if(profileError)throw profileError;
      let nextProfile=existing;
      if(!nextProfile){const display=String(nextUser.user_metadata?.display_name||'Visitante').trim().slice(0,20);const {data,error}=await client.from('player_profiles').insert({id:nextUser.id,display_name:display.length>=2?display:'Visitante'}).select().single();if(error)throw error;nextProfile=data;}
      const {data:saved,error:saveError}=await client.from('player_saves').select('state').eq('user_id',nextUser.id).maybeSingle();if(saveError)throw saveError;
      if(current!==generation)return;user=nextUser;profile=nextProfile;profiles.set(user.id,profile);
      game.account(profile,saved?.state);fillProfile();$('online-login').hidden=true;$('online-connected').hidden=false;
      await client.realtime.setAuth(session.access_token);
      selfChannel=client.channel('player:'+user.id,{config:{private:true}}).subscribe(state=>{if(current!==generation)return;selfReady=state==='SUBSCRIBED';updateBadge();if(state==='CHANNEL_ERROR'||state==='TIMED_OUT')status('Reconectando à cidade. Suas missões ficam guardadas.');});
      accountChannel=client.channel('account-events-'+user.id)
        .on('postgres_changes',{event:'*',schema:'public',table:'conversations',filter:'a=eq.'+user.id},()=>scheduleRefresh())
        .on('postgres_changes',{event:'*',schema:'public',table:'conversations',filter:'b=eq.'+user.id},()=>scheduleRefresh())
        .on('postgres_changes',{event:'*',schema:'public',table:'coop_invites',filter:'recipient=eq.'+user.id},()=>scheduleRefresh())
        .on('postgres_changes',{event:'*',schema:'public',table:'coop_members',filter:'user_id=eq.'+user.id},()=>scheduleRefresh()).subscribe();
      await heartbeat();await refresh();status('Olá, '+profile.display_name+'! Escolha seu avatar ou convide um amigo.');selectTab('account');
    }finally{connecting=false;}
  }
  function scheduleRefresh(){clearTimeout(realtimeTimer);realtimeTimer=setTimeout(()=>run(refresh),120);}
  async function heartbeat(){if(!user)return;lastHeartbeat=Date.now();const {error}=await client.from('online_players').upsert({user_id:user.id});if(error)throw error;}
  async function refresh(){
    if(!user||refreshing)return;refreshing=true;const current=generation,myId=user.id;
    try{
      const results=await Promise.all([
        client.from('online_players').select('user_id,seen_at').neq('user_id',myId).gte('seen_at',new Date(Date.now()-45000).toISOString()).limit(32),
        client.from('player_blocks').select('blocked').eq('blocker',myId),
        client.from('conversations').select('*').or('a.eq.'+myId+',b.eq.'+myId).order('updated_at',{ascending:false}).limit(40),
        client.from('coop_invites').select('*').eq('recipient',myId).eq('status','pending').gte('created_at',new Date(Date.now()-300000).toISOString()),
        client.from('coop_members').select('group_id').eq('user_id',myId).maybeSingle()
      ]);for(const r of results)if(r.error)throw r.error;if(current!==generation)return;
      blocked=new Set(results[1].data.map(x=>x.blocked));conversations=results[2].data;invitations=results[3].data;
      if(results[0].data.length){const {data:updated,error}=await client.from('player_profiles').select('id,display_name,color,skin,hair').in('id',results[0].data.map(p=>p.user_id));if(error)throw error;for(const p of updated)profiles.set(p.id,p);}
      const newRoster=new Map();for(const row of results[0].data){if(blocked.has(row.user_id))continue;const p=await loadProfile(row.user_id);newRoster.set(p.id,p);if(!peerChannels.has(p.id)){const ch=client.channel('player:'+p.id,{config:{private:true}}).on('broadcast',{event:'pose'},({payload})=>{if(current===generation&&roster.has(p.id))game.peer(p.id,profiles.get(p.id)||p,payload);}).subscribe();peerChannels.set(p.id,ch);}}
      if(current!==generation)return;
      for(const id of roster.keys())if(!newRoster.has(id)){game.removePeer(id);const ch=peerChannels.get(id);if(ch)client.removeChannel(ch);peerChannels.delete(id);}roster=newRoster;
      const ids=new Set([...conversations.flatMap(c=>[c.a,c.b]),...invitations.map(i=>i.sender),...blocked]);await Promise.all([...ids].map(id=>loadProfile(id).catch(()=>null)));
      const member=results[4].data;if(member)await loadGroup(member.group_id);else if(group){if(groupChannel)await client.removeChannel(groupChannel);groupChannel=null;group=null;groupVersion=-1;members=[];game.leaveGroup();}
      if(current!==generation)return;renderPlayers();renderConversations();renderGroup();renderBlocked();updateBadge();if(activeChat)await loadMessages();
      for(const invitation of [...conversations.filter(c=>c.status==='pending'&&c.requested_by!==myId&&Date.parse(c.updated_at)>Date.now()-300000),...invitations]){if(!seenInvites.has(invitation.id)){seenInvites.add(invitation.id);game.toast('Você recebeu um convite. Abra Jogar com amigos.');}}
    }finally{refreshing=false;lastRefresh=Date.now();}
  }
  async function loadGroup(id){const {data,error}=await client.from('coop_groups').select('*').eq('id',id).single();if(error)throw error;const changed=group?.id!==id;if(changed){if(groupChannel)await client.removeChannel(groupChannel);groupVersion=-1;group={id};groupChannel=client.channel('coop-group-'+id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'coop_groups',filter:'id=eq.'+id},({new:row})=>{if(group?.id===id)applyGroup(row.state,row.version);}).subscribe();}applyGroup(data.state,data.version);const {data:people,error:peopleError}=await client.from('coop_members').select('user_id').eq('group_id',id);if(peopleError)throw peopleError;members=await Promise.all(people.map(p=>loadProfile(p.user_id)));}
  function applyGroup(state,version){if(!group||version<groupVersion)return;group.state=state;groupVersion=version;game.group(state);renderGroup();}
  function playerName(id){return profiles.get(id)?.display_name||'Jogador';}
  function renderPlayers(){
    const root=$('online-players');root.replaceChildren();if(!roster.size)root.append(el('p','Ainda não há outros jogadores online. Peça ao seu amigo para abrir este mesmo endereço e entrar na conta.','online-empty'));
    for(const p of roster.values()){const card=el('article',null,'online-player'),head=el('header'),swatch=el('i',null,'online-swatch');swatch.style.background=p.color;head.append(swatch,el('strong',p.display_name));card.append(head);const actions=el('div',null,'online-player-actions');actions.append(button('Conversar',()=>requestChat(p.id)),button('Convidar para missão',()=>confirmGroup(p.id)),button('Bloquear',async()=>{await rpc('block_player',{target:p.id});await refresh();},'online-small online-danger'));card.append(actions);root.append(card);}
    const invites=$('online-invites');invites.replaceChildren();
    for(const c of conversations.filter(c=>c.status==='pending'&&c.requested_by!==user.id&&Date.parse(c.updated_at)>Date.now()-300000&&!blocked.has(c.requested_by))){const card=el('div',null,'online-invite');card.append(el('p',playerName(c.requested_by)+' quer conversar por texto.'),button('Aceitar',async()=>{await rpc('respond_chat',{conversation:c.id,accept:true});await refresh();await openChat(c.id);}),button('Recusar',async()=>{await rpc('respond_chat',{conversation:c.id,accept:false});await refresh();}));invites.append(card);}
    for(const i of invitations){const card=el('div',null,'online-invite');card.append(el('p',playerName(i.sender)+' convidou você para as missões do grupo. Sua partida individual ficará guardada.'),button('Jogar juntos',async()=>{await flushSave();await rpc('respond_coop',{invitation:i.id,accept:true});await refresh();selectTab('group');}),button('Recusar',async()=>{await rpc('respond_coop',{invitation:i.id,accept:false});await refresh();}));invites.append(card);}
  }
  async function requestChat(id){const c=await rpc('request_chat',{target:id});await refresh();const found=conversations.find(x=>x.id===c);if(found?.status==='accepted')await openChat(c);else if(found?.requested_by===user.id)notice('Convite enviado. Aguarde o outro jogador aceitar.');else{selectTab('players');notice('Esse jogador também convidou você. Aceite o convite acima.');}}
  function renderConversations(){const root=$('online-conversations');root.replaceChildren();const accepted=conversations.filter(c=>c.status==='accepted'&&!blocked.has(c.a===user.id?c.b:c.a));if(!accepted.length)root.append(el('p','Convide alguém na aba Jogadores. A conversa aparecerá aqui depois de aceita.','online-empty'));for(const c of accepted){const other=c.a===user.id?c.b:c.a;root.append(button(playerName(other),()=>openChat(c.id)));}if(activeChat&&!accepted.some(c=>c.id===activeChat))closeActiveChat();}
  async function openChat(id){const c=conversations.find(x=>x.id===id&&x.status==='accepted');if(!c)throw new Error('A conversa ainda não foi aceita.');if(chatChannel)await client.removeChannel(chatChannel);activeChat=id;$('online-chat-name').textContent='Conversa com '+playerName(c.a===user.id?c.b:c.a);$('online-active-chat').hidden=false;selectTab('chat');chatChannel=client.channel('chat-'+id).on('postgres_changes',{event:'INSERT',schema:'public',table:'chat_messages',filter:'conversation_id=eq.'+id},()=>run(loadMessages)).subscribe();await loadMessages();}
  function closeActiveChat(){activeChat=null;$('online-active-chat').hidden=true;$('online-messages').replaceChildren();if(chatChannel){client.removeChannel(chatChannel);chatChannel=null;}}
  async function loadMessages(){const id=activeChat;if(!id||!user)return;const {data,error}=await client.from('chat_messages').select('id,sender,body,created_at').eq('conversation_id',id).order('created_at',{ascending:false}).limit(100);if(error)throw error;if(activeChat!==id)return;const root=$('online-messages'),nearBottom=root.scrollHeight-root.scrollTop-root.clientHeight<55;root.replaceChildren();for(const m of data.reverse()){const row=el('div',null,'online-message'+(m.sender===user.id?' mine':''));row.append(el('b',m.sender===user.id?'Você':playerName(m.sender)),el('span',m.body));root.append(row);}if(nearBottom||root.scrollTop===0)root.scrollTop=root.scrollHeight;}
  function confirmGroup(id){pendingInvite=id;if(!$('online-group-confirm').open)$('online-group-confirm').showModal();}
  function renderGroup(){const root=$('online-group-summary');root.replaceChildren();$('online-leave-group').hidden=!group;if(!group){root.append(el('strong','Você está na sua partida individual.'),el('p','Na aba Jogadores, convide um amigo para começar uma campanha em grupo.'));return;}root.append(el('strong','Grupo · missão '+Math.min(26,(group.state?.step||0)+1)+'/26'),el('p',members.map(p=>p.display_name).join(' · ')||'Carregando integrantes…'),el('p',(group.state?.money??50)+' moedas compartilhadas'));}
  function renderBlocked(){const root=$('online-blocked');root.replaceChildren();if(blocked.size)root.append(el('p','Jogadores bloqueados'));for(const id of blocked)root.append(button('Desbloquear '+playerName(id),async()=>{await rpc('unblock_player',{target:id});await refresh();}));}
  async function act(target){
    if(!group||!user)return;if(busyAction){game.toast('Aguarde a confirmação da última ação.');return;}busyAction=true;const current=generation,id=group.id,eventId=uuid();
    try{const {data}=await client.auth.getSession();if(!data.session)throw new Error('Entre novamente na sua conta.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);let response;try{response=await fetch('/api/coop',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.session.access_token},body:JSON.stringify({groupId:id,eventId,action:{target,...game.pose()}}),signal:controller.signal});}finally{clearTimeout(timer);}const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível salvar a ação.');if(current!==generation||group?.id!==id)return;applyGroup(result.state,result.version);game.effect(result.effect);game.toast(result.message);}
    catch(e){game.toast(errorText(e));await run(refresh);}finally{busyAction=false;}
  }
  async function flushSave(){clearTimeout(saveTimer);if(saving){await saving;if(pendingSave)return flushSave();return;}if(!pendingSave||!user)return;const snapshot=pendingSave,myId=user.id,current=generation;pendingSave=null;saving=(async()=>{const {error}=await client.from('player_saves').upsert({user_id:myId,state:snapshot});if(current!==generation)return;if(error){pendingSave=pendingSave||snapshot;$('online-save-status').textContent='Salvamento local mantido; aguardando conexão para salvar na conta.';throw error;}$('online-save-status').textContent='Partida individual salva na sua conta.';})();try{await saving;}finally{saving=null;}}
  window.CerroOnline={
    saveSolo(snapshot){if(!user||group)return;pendingSave=JSON.parse(JSON.stringify(snapshot));clearTimeout(saveTimer);saveTimer=setTimeout(()=>flushSave().catch(()=>{}),900);},
    interact(n){if(n.type==='remote-player'){openPanel('players');return true;}if(group){if(n.type==='bench'||(n.type==='animal'&&n.id!=='animal0'))return false;if(!['ana','jose','clara','miguel','trash0','trash1','trash2','ivo','rosa','lurdes','lenhador','rita','dito','lia','joaquim','bia','picnic-spot','caio','mercado','hortifruti','animal0','lost-ball','signal-crossing','elisa','davi','secret-entrance','rescue','tunnel-exit'].includes(n.id)){game.toast('Converse com o personagem indicado no objetivo do grupo.');return true;}act(n.id);return true;}return false;},act,
    frame(t){if(!user)return;const now=Date.now();if(selfReady&&t-lastPose>.12){const pose=game.pose(),text=JSON.stringify(pose);if(text!==lastPoseText||t-lastPose>1){lastPose=t;lastPoseText=text;selfChannel.send({type:'broadcast',event:'pose',payload:pose}).catch(()=>{});}}if(now-lastHeartbeat>15000){lastHeartbeat=now;heartbeat().catch(()=>{});}if(now-lastRefresh>5000&&!refreshing){lastRefresh=now;refresh().catch(()=>status('Reconectando. Suas ações serão confirmadas quando a conexão voltar.'));}}
  };
  $('online-launcher').onclick=()=>openPanel();$('welcome-online').onclick=()=>openPanel();$('online-close').onclick=closePanel;
  $('online-dialog').addEventListener('cancel',e=>{e.preventDefault();closePanel();});
  document.querySelectorAll('[data-online-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.onlineTab));
  function mode(value){signup=value;$('online-signup-fields').hidden=!value;$('online-mode-login').setAttribute('aria-selected',String(!value));$('online-mode-signup').setAttribute('aria-selected',String(value));$('online-submit').textContent=value?'Criar minha conta →':'Entrar na cidade →';$('online-password').autocomplete=value?'new-password':'current-password';$('online-new-name').required=value;}
  $('online-mode-login').onclick=()=>mode(false);$('online-mode-signup').onclick=()=>mode(true);
  $('online-auth').onsubmit=e=>{e.preventDefault();run(async()=>{if(!client)throw new Error('O modo online ainda não está disponível neste endereço.');const email=$('online-email').value.trim(),password=$('online-password').value;if(signup){const {data,error}=await client.auth.signUp({email,password,options:{data:{display_name:$('online-new-name').value.trim()},emailRedirectTo:location.origin}});if(error)throw error;$('online-password').value='';if(!data.session)status('Confira seu e-mail e confirme o cadastro. Depois volte e entre na conta.');else await connect(data.session);}else{const {data,error}=await client.auth.signInWithPassword({email,password});if(error)throw error;$('online-password').value='';await connect(data.session);}},$('online-submit'));};
  $('online-reset').onclick=()=>run(async()=>{if(!client)return;const email=$('online-email').value.trim();if(!email||!$('online-email').checkValidity())throw new Error('Preencha seu e-mail primeiro.');const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin});if(error)throw error;status('Se esse e-mail tiver uma conta, você receberá as instruções para trocar a senha.');});
  $('online-recovery').onsubmit=e=>{e.preventDefault();run(async()=>{const {error}=await client.auth.updateUser({password:$('online-new-password').value});if(error)throw error;$('online-new-password').value='';recovering=false;$('online-recovery').hidden=true;$('online-connected').hidden=!user;status('Senha atualizada. Você já pode continuar.');});};
  $('online-avatar-form').onsubmit=e=>{e.preventDefault();run(async()=>{if(!user)return;const next={id:user.id,display_name:$('online-display-name').value.trim(),color:$('online-color').value,skin:$('online-skin').value,hair:$('online-hair').value};const {error}=await client.from('player_profiles').upsert(next);if(error)throw error;profile=next;profiles.set(user.id,next);game.setProfile(next);window.CerroOnline.saveSolo(game.snapshot());notice('Seu avatar foi salvo.');});};
  for(const id of ['online-color','online-skin','online-hair'])$(id).oninput=avatarPreview;
  $('online-chat-form').onsubmit=e=>{e.preventDefault();const message=$('online-message').value.trim(),id=activeChat;if(!message||!id)return;run(async()=>{await rpc('send_chat',{conversation:id,message,nonce:uuid()});if(activeChat===id)$('online-message').value='';await loadMessages();},e.submitter);};
  $('online-end-chat').onclick=()=>run(async()=>{if(activeChat)await rpc('close_chat',{conversation:activeChat});closeActiveChat();await refresh();});
  $('online-group-cancel').onclick=()=>$('online-group-confirm').close();$('online-group-send').onclick=()=>run(async()=>{if(!pendingInvite)return;await flushSave();await rpc('invite_coop',{target:pendingInvite});$('online-group-confirm').close();await refresh();selectTab('group');notice('Convite enviado. Seu amigo pode aceitar em Jogar com amigos.');},$('online-group-send'));
  $('online-leave-group').onclick=()=>run(async()=>{await rpc('leave_coop',{});await refresh();notice('Você voltou à sua partida individual.');});
  $('online-signout').onclick=()=>run(async()=>{game.leaveGroup();await flushSave();if(user)await client.from('online_players').delete().eq('user_id',user.id);await teardown();const {error}=await client.auth.signOut();if(error)throw error;user=profile=null;game.guest();$('online-connected').hidden=true;$('online-login').hidden=false;status('Você saiu da conta. O passeio individual continua disponível.');updateBadge();});
  async function boot(){try{const response=await fetch('/api/config',{cache:'no-store'});if(!response.ok)throw new Error('Configuração indisponível.');const config=await response.json();if(!config.configured||!window.createOnlineClient){status('O modo online ainda não foi ativado neste endereço. Você pode jogar individualmente.');$('online-submit').disabled=true;return;}client=window.createOnlineClient(config.url,config.publishableKey);client.auth.onAuthStateChange((event,session)=>{setTimeout(()=>{if(event==='PASSWORD_RECOVERY'){recovering=true;openPanel('account');$('online-login').hidden=true;$('online-connected').hidden=true;$('online-recovery').hidden=false;}else if(event==='TOKEN_REFRESHED'){client.realtime.setAuth(session?.access_token);}else if(event==='SIGNED_OUT')run(()=>connect(null));else if(!recovering&&session)run(()=>connect(session));},0);});const {data,error}=await client.auth.getSession();if(error)throw error;await connect(data.session);if(!data.session)status('Crie sua conta ou entre para encontrar outros jogadores.');}catch(e){status('O modo online precisa de uma conexão com o servidor. A partida individual continua disponível.');}}
  boot();
})();
